import Darwin
import Dispatch
import Foundation
import PkgLiftCore
import XCTest
@testable import PkgLiftCLI

/// Exact project.xcproj files generated by upstream XcodeProj 9.17.5 from
/// Fixtures/PartialSwift. These frozen bytes also compile with XcodeProj 9.16.0.
/// The explicit variant previously yielded a real KeychainAccess AUTO plan and
/// created a second project definition during apply. The implicit variant
/// lacks source-type evidence; both formats must be refused before analysis.
final class UnsupportedProjectFormatTests: XCTestCase {
    private static let childApplyRoot = "PKGLIFT_UNSUPPORTED_FORMAT_APPLY_ROOT"
    private static let projectName = "SwiftKeychainAccess.xcodeproj"

    func testJSONOnlyExplicitSwiftTypesRefusedAtEveryCLIEntry() async throws {
        try await assertCommandsRefuse(.explicit)
    }

    func testJSONOnlyImplicitSwiftTypesRefusedAtEveryCLIEntry() async throws {
        try await assertCommandsRefuse(.implicit)
    }

    func testDualProjectDefinitionsRefusedAtEveryCLIEntry() async throws {
        try await assertCommandsRefuse(.dual)
    }

    /// Apply uses signal handlers if it unexpectedly reaches migration. A
    /// separate XCTest process keeps that path isolated from the test runner.
    func testChildProcessRefusesUnsupportedApply() async throws {
        guard let root = ProcessInfo.processInfo.environment[Self.childApplyRoot] else {
            return
        }
        let project = URL(fileURLWithPath: root, isDirectory: true)
            .appendingPathComponent(Self.projectName, isDirectory: true)
        var command = try MigrateCommand.parse([
            "--path", root, "--project", project.path, "--apply",
        ])
        await assertUnsupported { try await command.run() }
    }

    private func assertCommandsRefuse(_ mode: Mode) async throws {
        var fixture = try Fixture(mode: mode)
        defer { try? FileManager.default.removeItem(at: fixture.root) }
        try await fixture.prepare()
        let arguments = ["--path", fixture.root.path, "--project", fixture.project.path]
        let savedBytes = try fixture.originalBytes()
        XCTAssertEqual(try gitOutput(["status", "--porcelain"], in: fixture.root), "")

        var analyze = try AnalyzeCommand.parse(arguments)
        await assertUnsupported { try await analyze.run() }
        try fixture.assertUnchanged(savedBytes)

        var plan = try PlanCommand.parse(arguments)
        await assertUnsupported { try await plan.run() }
        try fixture.assertUnchanged(savedBytes)

        var dryRun = try MigrateCommand.parse(arguments)
        await assertUnsupported { try await dryRun.run() }
        try fixture.assertUnchanged(savedBytes)

        var verify = try VerifyCommand.parse(arguments)
        await assertUnsupported { try await verify.run() }
        try fixture.assertUnchanged(savedBytes)

        try runApplyInFreshXCTestProcess(root: fixture.root)
        try fixture.assertUnchanged(savedBytes)
        XCTAssertEqual(try gitOutput(["status", "--porcelain"], in: fixture.root), "")
    }

    private func assertUnsupported(_ operation: () async throws -> Void) async {
        do {
            try await operation()
            XCTFail("Unsupported project.xcproj was accepted")
        } catch {
            let diagnostic = error.localizedDescription.lowercased()
            XCTAssertTrue(diagnostic.contains("unsupported"), diagnostic)
            XCTAssertTrue(diagnostic.contains("project.xcproj"), diagnostic)
        }
    }

    private func runApplyInFreshXCTestProcess(root: URL) throws {
        let lookup = Process()
        lookup.executableURL = URL(fileURLWithPath: "/usr/bin/xcrun")
        lookup.arguments = ["--find", "xctest"]
        let lookupOutput = Pipe()
        lookup.standardOutput = lookupOutput
        lookup.standardError = FileHandle.nullDevice
        try lookup.run()
        lookup.waitUntilExit()
        guard lookup.terminationStatus == 0 else { throw TestError.xctestUnavailable }
        let executable = String(
            decoding: lookupOutput.fileHandleForReading.readDataToEndOfFile(),
            as: UTF8.self
        ).trimmingCharacters(in: .whitespacesAndNewlines)
        guard !executable.isEmpty else { throw TestError.xctestUnavailable }

        let process = Process()
        process.executableURL = URL(fileURLWithPath: executable)
        process.arguments = [
            "-XCTest",
            "PkgLiftCLITests.UnsupportedProjectFormatTests/testChildProcessRefusesUnsupportedApply",
            Bundle(for: Self.self).bundleURL.path,
        ]
        var environment = ProcessInfo.processInfo.environment
        environment[Self.childApplyRoot] = root.path
        process.environment = environment
        process.standardOutput = FileHandle.nullDevice
        let standardError = Pipe()
        process.standardError = standardError
        let finished = DispatchSemaphore(value: 0)
        process.terminationHandler = { _ in finished.signal() }
        try process.run()
        guard finished.wait(timeout: .now() + 30) == .success else {
            _ = Darwin.kill(process.processIdentifier, SIGKILL)
            process.waitUntilExit()
            throw TestError.childTimedOut
        }
        let diagnostic = String(
            decoding: standardError.fileHandleForReading.readDataToEndOfFile(),
            as: UTF8.self
        )
        XCTAssertEqual(process.terminationReason, .exit, diagnostic)
        XCTAssertEqual(process.terminationStatus, 0, diagnostic)
    }

