    private struct Fixture {
        let root: URL
        let project: URL
        let xcproj: URL
        let pbxproj: URL
        let plan: URL
        let mode: Mode

        init(mode: Mode) throws {
            self.mode = mode
            let checkout = URL(fileURLWithPath: #filePath)
                .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            let source = checkout.appendingPathComponent("Fixtures/PartialSwift", isDirectory: true)
            let temporaryRoot: URL
            if let selected = ProcessInfo.processInfo.environment["PKGLIFT_TEST_TEMP_ROOT"] {
                var isDirectory: ObjCBool = false
                guard !selected.isEmpty,
                      FileManager.default.fileExists(atPath: selected, isDirectory: &isDirectory),
                      isDirectory.boolValue else {
                    throw TestError.invalidTemporaryRoot(selected)
                }
                temporaryRoot = URL(fileURLWithPath: selected, isDirectory: true)
            } else {
                temporaryRoot = FileManager.default.temporaryDirectory
            }
            root = temporaryRoot
                .appendingPathComponent("PkgLiftUnsupportedFormat-\(mode.name)-\(UUID().uuidString)", isDirectory: true)
            try FileManager.default.copyItem(at: source, to: root)
            project = root.appendingPathComponent(UnsupportedProjectFormatTests.projectName, isDirectory: true)
            pbxproj = project.appendingPathComponent("project.pbxproj")
            xcproj = project.appendingPathComponent("project.xcproj")
            plan = root.appendingPathComponent(".pkglift/plan.json")
        }

        func prepare() async throws {
            // Generate a real, registry-backed saved plan on the supported
            // project. Its KeychainAccess AUTO route is the apply precondition.
            let arguments = ["--path", root.path, "--project", project.path]
            var planCommand = try PlanCommand.parse(arguments)
            try await planCommand.run()
            let decoder = JSONDecoder()
            decoder.dateDecodingStrategy = .iso8601
            let savedPlan = try decoder.decode(MigrationPlan.self, from: Data(contentsOf: plan))
            XCTAssertEqual(savedPlan.autoEntries.map(\.podName), ["KeychainAccess"])
            guard savedPlan.autoEntries.map(\.podName) == ["KeychainAccess"] else {
                throw TestError.supportedPlanMissingAuto
            }
            var dryRun = try MigrateCommand.parse(arguments)
            try await dryRun.run()

            if mode != .dual {
                try FileManager.default.removeItem(at: pbxproj)
            }
            try Data(mode.json.utf8).write(to: xcproj)
            try ".pkglift/plan.json\n".write(
                to: root.appendingPathComponent(".gitignore"),
                atomically: true,
                encoding: .utf8
            )
            try runGit(["init", "--quiet"], in: root)
            try runGit(["config", "user.email", "format-test@example.invalid"], in: root)
            try runGit(["config", "user.name", "PkgLift Format Test"], in: root)
            try runGit(["config", "commit.gpgsign", "false"], in: root)
            try runGit(["add", "."], in: root)
            try runGit(["commit", "--quiet", "-m", "supported-plan baseline"], in: root)
        }

        func originalBytes() throws -> [URL: Data] {
            var files = [
                root.appendingPathComponent("Podfile"),
                root.appendingPathComponent("Podfile.lock"),
                root.appendingPathComponent(".pkglift.yml"),
                root.appendingPathComponent(".gitignore"),
                root.appendingPathComponent("App/AppDelegate.swift"),
                root.appendingPathComponent("App/Consumer.swift"),
                root.appendingPathComponent("App/Fixture.txt"),
                project.appendingPathComponent("xcshareddata/xcschemes/SwiftKeychainAccess.xcscheme"),
                xcproj,
                plan,
            ]
            if mode == .dual { files.append(pbxproj) }
            var bytes: [URL: Data] = [:]
            for file in files { bytes[file] = try Data(contentsOf: file) }
            return bytes
        }

        func assertUnchanged(_ savedBytes: [URL: Data]) throws {
            for (file, original) in savedBytes {
                XCTAssertEqual(try Data(contentsOf: file), original, file.path)
            }
            XCTAssertFalse(
                FileManager.default.fileExists(atPath: root.appendingPathComponent(".pkglift/backup").path),
                "Unsupported format must be refused before backup creation"
            )
            let children = try Set(FileManager.default.contentsOfDirectory(atPath: project.path))
            let expected: Set<String> = mode == .dual
                ? ["project.xcproj", "project.pbxproj", "xcshareddata"]
                : ["project.xcproj", "xcshareddata"]
            XCTAssertEqual(children, expected)
        }
    }

    private enum TestError: LocalizedError {
        case xctestUnavailable
        case childTimedOut
        case supportedPlanMissingAuto
        case invalidTemporaryRoot(String)

        var errorDescription: String? {
            switch self {
            case .xctestUnavailable: "Could not find xctest"
            case .childTimedOut: "Apply child process timed out"
            case .supportedPlanMissingAuto: "Supported fixture did not produce KeychainAccess AUTO"
            case .invalidTemporaryRoot(let path): "Test temporary root is unavailable: \(path)"
            }
        }
    }
}

private func runGit(_ arguments: [String], in root: URL) throws {
    _ = try gitOutput(arguments, in: root)
}

private func gitOutput(_ arguments: [String], in root: URL) throws -> String {
    let process = Process()
    process.executableURL = URL(fileURLWithPath: "/usr/bin/git")
    process.arguments = arguments
    process.currentDirectoryURL = root
    let output = Pipe()
    process.standardOutput = output
    process.standardError = output
    try process.run()
    process.waitUntilExit()
    let value = String(decoding: output.fileHandleForReading.readDataToEndOfFile(), as: UTF8.self)
    guard process.terminationStatus == 0 else {
        throw GitTestError.failed(arguments.joined(separator: " "), value)
    }
    return value.trimmingCharacters(in: .whitespacesAndNewlines)
}

private enum GitTestError: LocalizedError {
    case failed(String, String)

    var errorDescription: String? {
        switch self {
        case .failed(let arguments, let output): "git \(arguments) failed: \(output)"
        }
    }
}
